// Square root using iterative method
function MySqrt(x: real): real;
begin
  var eps := 1e-15;
  (var a, var b) := (x, real.MaxValue);
  while abs(b-a) >= eps do
    (a,b) := (b,(a + x / a) / 2);
  Result := b;  
end;

begin
  Println(MySqrt(2));
  Println(MySqrt(3));
  Println(MySqrt(4));
end.

// Newton's method for equation solving
function f(x: real) := exp(x) - 4;
function df(x: real) := exp(x);

function NewtonMethod(x, eps: real): real;
begin
  while abs(f(x)) > eps do
    x := x - f(x) / df(x); 
  Result := x;
end;

begin
  var x := 0.5;
  var eps := 0.00001;
  var root := NewtonMethod(x, eps);
  Println('Equation root: ', root);
end.

